    if(knn)traces.push({type:'scatter',mode:'lines',x:[0,100],y:[0,100],name:'Equal contribution from every protein',line:{color:'#6e7f8a',dash:'dot',width:1.5},hoverinfo:'skip'});
    await draw(card,traces,{xaxis:{title:'Proteins included (% of full panel)<br>largest additive contributions first',range:[0,100]},yaxis:{title:knn?'Cumulative share of total observed overlap (%)':'Cumulative contribution to global CKA<br>(dimensionless)',...(knn?{range:[0,103]}:{})}},rows);
    content(grid,'Concentration at fixed descriptive thresholds',tableHTML(['Comparison checkpoint','Proteins included','Cumulative allocation'],thresholds.map(row=>row.map(esc)))+'<p class="definition">These fixed-size summaries break boundary ties by protein ID; all tied proteins have the same contribution. Use “Include all boundary ties” for a selected group.</p>');
