      traces.push({type:'scatter',mode:'lines',x:xs,y:ys,name:`${label} (n=${order.length})`,line:{color,dash,width:2.3,shape:'hv'},hovertemplate:`${esc(label)}<br>${esc(modelLabel(state.a))} minus ${esc(modelLabel(state.b))}<br>${esc(valueLabel())}: %{x:.3g}<br>Finite pairs at or below: %{y:.3g}%<extra></extra>`});
      summaries.push([label,order.length,indices.length-order.length,fmt(sum(order.map(i=>difference[i]))/order.length,8),fmt(median,8),fmt(100*order.filter(i=>difference[i]>0).length/order.length,3)+'%',fmt(100*order.filter(i=>difference[i]===0).length/order.length,3)+'%',fmt(100*order.filter(i=>difference[i]<0).length/order.length,3)+'%']);
