    await draw(global,traces,{xaxis:{title:'Qwen model size',type:'log',tickvals:qs.map(q=>q.size_b),ticktext:qs.map(q=>q.size_b+'B')},yaxis:{title:state.metric==='knn'?`Global mean local overlap (k=${state.k})<br>(fraction across all ${N} proteins)`:'Global centered-Gram CKA score<br>(dimensionless)'},legend:{orientation:'h',y:1.08,x:0,font:{size:10}},margin:{b:80}},globalRows);
