    const sections=[['status','Which requested analyses are available?','all'],['archive_audit','Do legacy archive differences follow the recorded neighbor ties?'],['influence_validation','Do deletion calculations reproduce independent exact refits?'],['name_baseline','How much alignment is reproduced by protein names alone?','names'],['name_baseline_contrasts','How does Qwen–PLM alignment compare with the name baseline?'],['pair_classes','Which relationships account for alignment?'],['homology_summary','How much alignment comes from all detected homologs, including matching names?'],['name_controls','What changes after controlling repeated protein names?'],['name_mask_controls','What changes when same-name relationships are masked?'],['bootstrap','How does alignment vary across component-resampling draws?'],['controlled_contrasts','How do the controlled checkpoint contrasts compare?'],['scaling_interactions','Does this Pfam group change differently with Qwen size?']];
