      if(key==='scaling_interactions')rows.sort((a,b)=>Number(finite(b.lower)&&finite(b.upper))-Number(finite(a.lower)&&finite(a.upper))||(b.n_group_components??0)-(a.n_group_components??0)||groupLabel(a.group||'').localeCompare(groupLabel(b.group||'')));
      const priority=key==='scaling_interactions'?['plm_model','metric','group','coefficient','lower','upper','ci_unavailable_reason','n_group_components','n_rest_components','n_group_proteins','p_value','by_adjusted_p','p_unavailable_reason']:[];
      const columns=[...priority,...new Set(rows.flatMap(Object.keys).filter(key=>!priority.includes(key)))];const preview=rows.slice(0,200);const display=(key,value)=>{if(value===null||value===undefined)return 'Unavailable';if(typeof value==='number')return fmt(value,10);if(typeof value==='boolean')return value?'Yes':'No';if(typeof value==='object')return esc(JSON.stringify(value));if(key==='group')return `<span title="${esc(value)}">${esc(groupLabel(value))}</span>`;if(['qwen_model','plm_model','model_id'].includes(key))return esc(modelLabel(value));return esc(key==='class'?classLabels[value]||String(value).replace(/_/g,' '):value);};
