      let countExample='';if(key==='pair_classes'){const exclusive=rows.find(row=>row.class==='detected homolog'),inclusive=exclusive?review.homology_summary?.find(row=>row.class==='among detected homologs'&&row.qwen_model===exclusive.qwen_model&&row.plm_model===exclusive.plm_model&&row.metric===exclusive.metric):null;if(finite(exclusive?.ordered_pair_count)&&finite(inclusive?.ordered_pair_count)&&exclusive.ordered_pair_count%2===0&&inclusive.ordered_pair_count%2===0&&inclusive.ordered_pair_count>=exclusive.ordered_pair_count)countExample=`<p class="definition">In the recorded panel, counting each protein pair once gives <strong>${fmt(inclusive.ordered_pair_count/2,0)} detected homolog pairs</strong>: ${fmt((inclusive.ordered_pair_count-exclusive.ordered_pair_count)/2,0)} also share recorded names and enter the name row; ${fmt(exclusive.ordered_pair_count/2,0)} enter the different-name homolog row. The tables below count both ordered directions.</p>`;}
      const rawRange=['bootstrap','name_baseline_contrasts','controlled_contrasts'].includes(key);
      const rangeWarning=rawRange?'<p class="notice warning"><strong>Central 95% component-resampling range (uncalibrated).</strong> These raw ranges can be substantially shifted from the observed statistic. They are not calibrated confidence intervals. <strong>Do not infer a contrast sign or significance from zero exclusion in these raw ranges.</strong> The resampling mean, shift from the observation, and observed percentile show this behavior directly. Q3 group intervals have separate conditional methods.</p>':'';
